// Claude Bridge relay (Supabase Edge Function)
//
// Relays messages between the PC (server.js), the game (MCP_Bridge.lua) and, optionally,
// ChatGPT (remote MCP endpoint at /claude-bridge/mcp/<key>).
// - No API key in any client (verify_jwt = false); it authenticates itself:
//     PC      = owner secret (generated on the PC, only its hash is stored here)
//     game    = device token (issued by pairing with a 6-digit code, only its hash is stored)
//     ChatGPT = MCP key in the URL (generated by the owner, only its hash is stored, revocable)
// - Tables have RLS on with no policies: only the service role inside this function can access them.

import { createClient } from "jsr:@supabase/supabase-js@2";

const db = createClient(Deno.env.get("SUPABASE_URL")!, Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!, {
	auth: { persistSession: false },
});

const VERSION = "4.0.0";
const PAIR_TTL_MS = 10 * 60 * 1000; // 6-digit code lifetime
const MAX_PAIR_FAILS = 5;           // wrong attempts before the code is revoked
const PC_ONLINE_MS = 60 * 1000;     // game uses fast long-polling while a controller was seen recently
const CLIENT_STALE_MS = 45 * 1000;
const POLL_MS = 50;                 // how often a waiting request checks for new messages
const AUTH_CACHE_MS = 15 * 1000;    // per-isolate cache of successful auth checks
const MAX_EXEC_TIMEOUT_S = 120;
const enc = new TextEncoder();

async function sha(s: string): Promise<string> {
	const h = await crypto.subtle.digest("SHA-256", enc.encode(s));
	return [...new Uint8Array(h)].map((b) => b.toString(16).padStart(2, "0")).join("");
}
function randHex(bytes: number): string {
	const a = new Uint8Array(bytes);
	crypto.getRandomValues(a);
	return [...a].map((b) => b.toString(16).padStart(2, "0")).join("");
}
function sixDigits(): string {
	const a = new Uint32Array(1);
	do crypto.getRandomValues(a); while (a[0] >= 4294000000); // avoid modulo bias
	return String(a[0] % 1000000).padStart(6, "0");
}
const json = (o: unknown, status = 200) =>
	new Response(JSON.stringify(o), { status, headers: { "Content-Type": "application/json", "Cache-Control": "no-store" } });
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
// Run work after the response without blocking it.
function background(work: PromiseLike<unknown>) {
	// query builders are thenables without .catch: wrap them in a real Promise
	const p = Promise.resolve(work).catch(() => {});
	try { (globalThis as any).EdgeRuntime?.waitUntil?.(p); } catch { /* ignore */ }
}
function cleanId(v: unknown) {
	return String(v ?? "default").slice(0, 64);
}

// ------------------------------------------------------------------ auth
const authCache = new Map<string, number>();
function cached(key: string) {
	const exp = authCache.get(key);
	if (exp && exp > Date.now()) return true;
	if (exp) authCache.delete(key);
	return false;
}
function remember(key: string) {
	if (authCache.size > 500) authCache.clear();
	authCache.set(key, Date.now() + AUTH_CACHE_MS);
}

async function getOwner() {
	const { data, error } = await db.from("bridge_owner").select("*").eq("id", 1).single();
	if (error) throw error;
	return data;
}
async function isOwner(secret: unknown) {
	if (typeof secret !== "string" || secret.length < 32) return false;
	const h = await sha(secret);
	if (cached("o:" + h)) return true;
	const o = await getOwner();
	const ok = !!o.secret_hash && o.secret_hash === h;
	if (ok) remember("o:" + h);
	return ok;
}
async function isDevice(token: unknown) {
	if (typeof token !== "string" || token.length < 32) return false;
	const h = await sha(token);
	if (cached("d:" + h)) return true;
	const { data } = await db.from("bridge_devices").select("token_hash").eq("token_hash", h).maybeSingle();
	if (data) remember("d:" + h);
	return !!data;
}
async function isMcpKey(key: unknown) {
	if (typeof key !== "string" || key.length < 32) return false;
	const h = await sha(key);
	if (cached("m:" + h)) return true;
	const o = await getOwner();
	const ok = !!o.mcp_key_hash && o.mcp_key_hash === h;
	if (ok) remember("m:" + h);
	return ok;
}

// ------------------------------------------------------------------ messaging
// Long-poll: wait for messages on any of the channels, delete them as they are delivered.
async function consume(channels: string[], waitMs: number, signal: AbortSignal) {
	const deadline = Date.now() + waitMs;
	for (;;) {
		const { data, error } = await db.from("bridge_messages").select("id, body").in("channel", channels).order("id").limit(200);
		if (error) throw error;
		if (data.length) {
			if (signal.aborted) return [];
			const { data: del, error: e2 } = await db.from("bridge_messages").delete().in("id", data.map((m) => m.id)).select("id, body");
			if (e2) throw e2;
			if (del.length) return del.sort((a, b) => a.id - b.id).map((m) => m.body);
		}
		if (Date.now() >= deadline || signal.aborted) return [];
		await sleep(POLL_MS);
	}
}

let lastSeenWrite = 0;
function markControllerSeen() {
	if (Date.now() - lastSeenWrite < 5000) return;
	lastSeenWrite = Date.now();
	background(db.from("bridge_owner").update({ pc_seen: new Date().toISOString() }).eq("id", 1));
}

async function listClients() {
	const { data } = await db.from("bridge_clients").select("client_id, info, last_seen");
	return data ?? [];
}

// Send one command to a game and wait for its result on a private channel.
// Command ids look like "<inbox>~<n>"; game_send routes the result to channel "pc:<inbox>".
async function execOnGame(to: string, body: Record<string, unknown>, waitMs: number, signal: AbortSignal) {
	const id = String(body.id ?? "");
	const tilde = id.indexOf("~");
	if (tilde <= 0) throw new Error("command id must look like <inbox>~<n>");
	const inbox = "pc:" + cleanId(id.slice(0, tilde));
	const { error } = await db.from("bridge_messages").insert({ channel: "game:" + cleanId(to), body });
	if (error) throw error;
	markControllerSeen();
	const deadline = Date.now() + waitMs;
	while (Date.now() < deadline && !signal.aborted) {
		const msgs = await consume([inbox], deadline - Date.now(), signal);
		const r = msgs.find((m: any) => m && m.kind === "result" && String(m.id) === id);
		if (r) return r;
	}
	return null;
}

async function cleanup() {
	const old = new Date(Date.now() - 15 * 60 * 1000).toISOString();
	await db.from("bridge_messages").delete().lt("created_at", old);
	const day = new Date(Date.now() - 24 * 3600 * 1000).toISOString();
	await db.from("bridge_clients").delete().lt("last_seen", day);
}

// ------------------------------------------------------------------ remote MCP (ChatGPT)
const MCP_TOOLS = [
	{
		name: "roblox_status",
		description: "Check which Roblox game clients are connected (player, PlaceId, JobId, executor, device). Call this first.",
		inputSchema: { type: "object", properties: {} },
		annotations: { readOnlyHint: true },
	},
	{
		name: "roblox_execute",
		description:
			"Run Luau code in the user's connected Roblox game through their executor. Returns print/warn output, return values, " +
			"or the error with traceback. Globals assigned without `local` persist between runs. A helper inspect(value) is available. " +
			"Code running longer than `timeout` returns partial output and keeps running in the background.",
		inputSchema: {
			type: "object",
			properties: {
				code: { type: "string", description: "Luau source" },
				timeout: { type: "number", description: "Seconds to wait for the result (default 15, max 120)" },
				clientId: { type: "string", description: "Target client (from roblox_status). Default: most recently active." },
			},
			required: ["code"],
		},
	},
	{
		name: "roblox_get_logs",
		description: "Read the game's recent console output (print/warn/error from all scripts).",
		inputSchema: {
			type: "object",
			properties: {
				limit: { type: "number", description: "Max lines, newest kept (default 100, max 500)" },
				filter: { type: "string", description: "Only lines containing this text (case-insensitive)" },
				errorsOnly: { type: "boolean", description: "Only warnings and errors" },
				clientId: { type: "string" },
			},
		},
		annotations: { readOnlyHint: true },
	},
	{
		name: "roblox_get_tree",
		description: "Show the Instance hierarchy (like Explorer) with ClassName, values and attributes. path e.g. 'Workspace.__THINGS'.",
		inputSchema: {
			type: "object",
			properties: {
				path: { type: "string", description: "Default 'game'" },
				depth: { type: "number", description: "Default 2" },
				maxChildren: { type: "number", description: "Default 50" },
				filter: { type: "string" },
				clientId: { type: "string" },
			},
		},
		annotations: { readOnlyHint: true },
	},
	{
		name: "roblox_inspect",
		description: "Details of one Instance: properties, attributes, tags, children. For a ModuleScript set require=true to see its returned value.",
		inputSchema: {
			type: "object",
			properties: { path: { type: "string" }, require: { type: "boolean" }, clientId: { type: "string" } },
			required: ["path"],
		},
		annotations: { readOnlyHint: true },
	},
];

const textResult = (t: string, isError = false) => ({ content: [{ type: "text", text: t.length > 60000 ? t.slice(0, 60000) + "\n... [truncated]" : t }], isError });

function formatExec(r: any) {
	const parts: string[] = [];
	if (r.output && r.output.length) parts.push("--- output ---\n" + r.output.join("\n"));
	if (r.ok) {
		if (r.returns && r.returns.length) parts.push("--- return ---\n" + r.returns.join("\n"));
		if (r.stillRunning) parts.push(`(still running in the background after ${r.elapsed ?? "?"}s; check roblox_get_logs)`);
		if (!parts.length) parts.push("(completed, no output)");
		return textResult(parts.join("\n\n"));
	}
	parts.push("--- error ---\n" + (r.error || "unknown error"));
	return textResult(parts.join("\n\n"), true);
}

// Lua long-bracket string literal that cannot be broken out of.
const luaStr = (s: string) => "[==[" + String(s).replace(/\]==\]/g, "] ==]") + "]==]";

async function pickClient(clientId: unknown) {
	const live = (await listClients())
		.filter((c: any) => Date.now() - Date.parse(c.last_seen) < CLIENT_STALE_MS)
		.sort((a: any, b: any) => Date.parse(b.last_seen) - Date.parse(a.last_seen));
	if (clientId) {
		if (!live.find((c: any) => c.client_id === clientId)) throw new Error(`Client "${clientId}" is not connected.`);
		return String(clientId);
	}
	if (!live.length) throw new Error("No Roblox game is connected. Ask the user to run MCP_Bridge.lua in their executor (it reconnects automatically once paired).");
	return live[0].client_id as string;
}

async function remoteCommand(args: any, type: string, payload: Record<string, unknown>, timeoutSec: number, signal: AbortSignal) {
	const to = await pickClient(args.clientId);
	const id = "m" + randHex(6) + "~1";
	// +20s: if no controller was online the game may be in slow polling mode (up to ~15s) for the first command
	const r = await execOnGame(to, { id, type, timeout: timeoutSec, ...payload }, (timeoutSec + 20) * 1000, signal);
	return r ?? { ok: false, error: `No response from the game within ${timeoutSec + 20}s (disconnected or frozen?)` };
}

async function mcpCallTool(name: string, args: any, signal: AbortSignal) {
	args = args && typeof args === "object" ? args : {};
	switch (name) {
		case "roblox_status": {
			markControllerSeen();
			const now = Date.now();
			const clients = (await listClients()).map((c: any) => ({
				clientId: c.client_id,
				connected: now - Date.parse(c.last_seen) < CLIENT_STALE_MS,
				lastSeenSecAgo: Math.round((now - Date.parse(c.last_seen)) / 1000),
				...(c.info || {}),
			}));
			return textResult(JSON.stringify({ relay: "ok", version: VERSION, clients }, null, 2));
		}
		case "roblox_execute": {
			if (typeof args.code !== "string" || !args.code.trim()) return textResult("`code` is required", true);
			const t = Math.min(Math.max(Number(args.timeout) || 15, 1), MAX_EXEC_TIMEOUT_S);
			return formatExec(await remoteCommand(args, "exec", { code: args.code, chunkName: "mcp_exec" }, t, signal));
		}
		case "roblox_get_logs": {
			const limit = Math.min(Math.max(Number(args.limit) || 100, 1), 500);
			const code = `local LS = game:GetService("LogService")
local f = ${args.filter ? luaStr(String(args.filter).toLowerCase()) : "nil"}
local errorsOnly = ${args.errorsOnly ? "true" : "false"}
local out = {}
for _, e in ipairs(LS:GetLogHistory()) do
	local t = e.messageType
	local bad = t == Enum.MessageType.MessageError or t == Enum.MessageType.MessageWarning
	if (not errorsOnly or bad) and (not f or string.find(string.lower(e.message), f, 1, true)) then
		local tag = t == Enum.MessageType.MessageError and "[ERROR] " or t == Enum.MessageType.MessageWarning and "[WARN] " or ""
		out[#out + 1] = os.date("%H:%M:%S", e.timestamp) .. " " .. tag .. e.message
	end
end
local first = math.max(1, #out - ${limit} + 1)
return table.concat(out, "\\n", first) .. "\\n(" .. (#out - first + 1) .. "/" .. #out .. " lines)"`;
			return formatExec(await remoteCommand(args, "exec", { code, chunkName: "get_logs" }, 10, signal));
		}
		case "roblox_get_tree": {
			const r: any = await remoteCommand(args, "tree", {
				path: args.path || "game",
				depth: args.depth !== undefined && Number(args.depth) >= 0 ? Math.min(Number(args.depth), 10) : 2,
				maxChildren: Number(args.maxChildren) > 0 ? Math.min(Number(args.maxChildren), 500) : 50,
				filter: args.filter || null,
			}, 20, signal);
			return r.ok ? textResult(String(r.tree || "")) : textResult(String(r.error || "error"), true);
		}
		case "roblox_inspect": {
			if (!args.path) return textResult("`path` is required", true);
			const r: any = await remoteCommand(args, "inspect", { path: String(args.path), require: !!args.require }, 20, signal);
			return r.ok ? textResult(String(r.text || "")) : textResult(String(r.error || "error"), true);
		}
		default:
			return textResult("Unknown tool: " + name, true);
	}
}

async function handleMcpMessage(msg: any, signal: AbortSignal) {
	if (!msg || typeof msg !== "object") return { jsonrpc: "2.0", id: null, error: { code: -32600, message: "Invalid request" } };
	const { id, method, params } = msg;
	const isRequest = id !== undefined && id !== null;
	if (!isRequest) return null; // notifications (e.g. notifications/initialized)
	try {
		switch (method) {
			case "initialize":
				return {
					jsonrpc: "2.0", id, result: {
						protocolVersion: (params && params.protocolVersion) || "2025-06-18",
						capabilities: { tools: {} },
						serverInfo: { name: "roblox-bridge", version: VERSION },
						instructions:
							"Live bridge to the user's Roblox game. Start with roblox_status. Use roblox_execute to run Luau and read the result or error " +
							"directly instead of asking the user to copy errors. Use roblox_get_logs for console output, roblox_get_tree / roblox_inspect to explore.",
					},
				};
			case "ping":
				return { jsonrpc: "2.0", id, result: {} };
			case "tools/list":
				return { jsonrpc: "2.0", id, result: { tools: MCP_TOOLS } };
			case "tools/call":
				try {
					return { jsonrpc: "2.0", id, result: await mcpCallTool(params?.name, params?.arguments, signal) };
				} catch (e) {
					return { jsonrpc: "2.0", id, result: textResult(String((e as Error)?.message ?? e), true) };
				}
			case "resources/list":
				return { jsonrpc: "2.0", id, result: { resources: [] } };
			case "prompts/list":
				return { jsonrpc: "2.0", id, result: { prompts: [] } };
			default:
				return { jsonrpc: "2.0", id, error: { code: -32601, message: "Method not found: " + method } };
		}
	} catch (e) {
		return { jsonrpc: "2.0", id, error: { code: -32603, message: String((e as Error)?.message ?? e) } };
	}
}

async function handleMcp(req: Request, key: string) {
	if (!(await isMcpKey(key))) return json({ error: "unauthorized" }, 401);
	if (req.method === "GET") return new Response("SSE stream not supported; use POST (streamable HTTP, JSON responses)", { status: 405, headers: { Allow: "POST" } });
	if (req.method === "DELETE") return new Response(null, { status: 204 });
	if (req.method !== "POST") return json({ error: "method not allowed" }, 405);
	let body: any;
	try { body = await req.json(); } catch { return json({ jsonrpc: "2.0", id: null, error: { code: -32700, message: "Parse error" } }, 400); }
	if (Array.isArray(body)) {
		const out = (await Promise.all(body.map((m) => handleMcpMessage(m, req.signal)))).filter(Boolean);
		return out.length ? json(out) : new Response(null, { status: 202 });
	}
	const out = await handleMcpMessage(body, req.signal);
	return out ? json(out) : new Response(null, { status: 202 });
}

// ------------------------------------------------------------------ HTTP entry
Deno.serve(async (req) => {
	const url = new URL(req.url);
	const mcpMatch = url.pathname.match(/\/mcp\/([A-Za-z0-9_-]{32,128})\/?$/);
	if (mcpMatch) {
		try { return await handleMcp(req, mcpMatch[1]); } catch (e) { return json({ error: "server error: " + ((e as Error)?.message ?? e) }, 500); }
	}

	if (req.method === "GET") return json({ ok: true, name: "claude-bridge", version: VERSION });
	if (req.method !== "POST") return json({ error: "method not allowed" }, 405);

	let b: Record<string, any>;
	try {
		b = await req.json();
	} catch {
		return json({ error: "bad json" }, 400);
	}
	if (Math.random() < 0.02) background(cleanup());

	try {
		switch (b.action) {
			// ---------------- PC ----------------
			case "setup": { // one time: bind the PC's owner secret
				const o = await getOwner();
				if (!o.setup_hash) return json({ error: "already set up (setup code is single-use)" }, 403);
				if (typeof b.setupCode !== "string" || (await sha(b.setupCode)) !== o.setup_hash) return json({ error: "invalid setup code" }, 403);
				if (typeof b.ownerSecret !== "string" || b.ownerSecret.length < 32) return json({ error: "owner secret too short" }, 400);
				await db.from("bridge_owner").update({ secret_hash: await sha(b.ownerSecret), setup_hash: null }).eq("id", 1);
				return json({ ok: true });
			}
			case "pc_newcode": {
				if (!(await isOwner(b.owner))) return json({ error: "unauthorized" }, 401);
				const code = sixDigits();
				await db.from("bridge_owner").update({
					pair_hash: await sha(code),
					pair_expires: new Date(Date.now() + PAIR_TTL_MS).toISOString(),
					pair_fails: 0,
				}).eq("id", 1);
				return json({ code, expiresInSec: PAIR_TTL_MS / 1000 });
			}
			case "pc_unpair": {
				if (!(await isOwner(b.owner))) return json({ error: "unauthorized" }, 401);
				await db.from("bridge_devices").delete().neq("token_hash", "");
				await db.from("bridge_clients").delete().neq("client_id", "");
				await db.from("bridge_owner").update({ pair_hash: null }).eq("id", 1);
				authCache.clear();
				return json({ ok: true });
			}
			case "pc_mcpkey": { // create (or revoke) the ChatGPT remote-MCP key; returned once, only the hash is stored
				if (!(await isOwner(b.owner))) return json({ error: "unauthorized" }, 401);
				if (b.revoke) {
					await db.from("bridge_owner").update({ mcp_key_hash: null }).eq("id", 1);
					authCache.clear();
					return json({ ok: true, revoked: true });
				}
				const key = randHex(32);
				await db.from("bridge_owner").update({ mcp_key_hash: await sha(key) }).eq("id", 1);
				authCache.clear();
				return json({ key });
			}
			case "pc_send": {
				if (!(await isOwner(b.owner))) return json({ error: "unauthorized" }, 401);
				const { error } = await db.from("bridge_messages").insert({ channel: "game:" + cleanId(b.to), body: b.body ?? {} });
				if (error) throw error;
				markControllerSeen();
				return json({ ok: true });
			}
			case "pc_exec": { // send a command and wait for its result in the same request
				if (!(await isOwner(b.owner))) return json({ error: "unauthorized" }, 401);
				const wait = Math.min(Math.max(Number(b.wait) || 30000, 1000), 140000);
				const result = await execOnGame(cleanId(b.to), b.body ?? {}, wait, req.signal);
				return json({ result });
			}
			case "pc_poll": {
				if (!(await isOwner(b.owner))) return json({ error: "unauthorized" }, 401);
				markControllerSeen();
				const wait = Math.min(Math.max(Number(b.wait) || 0, 0), 25000);
				// each PC server instance has its own inbox (several Claude windows may run at once)
				const inst = typeof b.instance === "string" && b.instance ? cleanId(b.instance) : null;
				const messages = await consume(inst ? ["pc:" + inst, "pc"] : ["pc"], wait, req.signal);
				const [clients, devices] = await Promise.all([
					listClients(),
					db.from("bridge_devices").select("token_hash", { count: "exact", head: true }),
				]);
				return json({ messages, clients, pairedDevices: devices.count ?? 0 });
			}

			// ---------------- game ----------------
			case "game_pair": {
				const o = await getOwner();
				if (!o.pair_hash || !o.pair_expires || Date.parse(o.pair_expires) < Date.now()) {
					return json({ error: "ไม่มีรหัสที่ใช้ได้ ขอรหัสใหม่จาก Claude" }, 403);
				}
				if (typeof b.code !== "string" || (await sha(b.code.trim())) !== o.pair_hash) {
					const fails = (o.pair_fails ?? 0) + 1;
					const dead = fails >= MAX_PAIR_FAILS;
					await db.from("bridge_owner").update(dead ? { pair_fails: fails, pair_hash: null } : { pair_fails: fails }).eq("id", 1);
					return json({ error: dead ? "รหัสผิดหลายครั้ง รหัสถูกยกเลิก ขอรหัสใหม่จาก Claude" : "รหัสไม่ถูกต้อง" }, 403);
				}
				const token = randHex(32);
				const player = String(b.info?.player ?? "unknown").slice(0, 64);
				await db.from("bridge_devices").insert({ token_hash: await sha(token), player });
				await db.from("bridge_owner").update({ pair_hash: null, pair_fails: 0 }).eq("id", 1);
				await db.from("bridge_messages").insert({ channel: "pc", body: { kind: "paired", player } });
				return json({ token });
			}
			case "game_poll": {
				if (!(await isDevice(b.token))) return json({ error: "unpaired" }, 401);
				const clientId = cleanId(b.clientId);
				const [, owner] = await Promise.all([
					db.from("bridge_clients").upsert({ client_id: clientId, info: b.info ?? {}, last_seen: new Date().toISOString() }),
					getOwner(),
				]);
				const pcOnline = !!owner.pc_seen && Date.now() - Date.parse(owner.pc_seen) < PC_ONLINE_MS;
				const wait = pcOnline ? Math.min(Math.max(Number(b.wait) || 0, 0), 10000) : 0;
				const commands = await consume(["game:" + clientId], wait, req.signal);
				return json({ commands, pcOnline });
			}
			case "game_send": {
				if (!(await isDevice(b.token))) return json({ error: "unpaired" }, 401);
				const clientId = cleanId(b.clientId);
				const list = Array.isArray(b.messages) ? b.messages.slice(0, 50) : [];
				if (list.length) {
					const { error } = await db.from("bridge_messages").insert(
						list.map((m: any) => {
							// command ids look like "<inbox>~<n>": route the result back to whoever sent it
							const id = m && m.kind === "result" ? String(m.id ?? "") : "";
							const tilde = id.indexOf("~");
							const channel = tilde > 0 ? "pc:" + cleanId(id.slice(0, tilde)) : "pc";
							return { channel, body: { ...(m ?? {}), clientId } };
						}),
					);
					if (error) throw error;
				}
				return json({ ok: true });
			}
			default:
				return json({ error: "unknown action" }, 400);
		}
	} catch (e) {
		return json({ error: "server error: " + ((e as Error)?.message ?? String(e)) }, 500);
	}
});
